package com.hirain.aiagent.rag.policy;
import com.hirain.aiagent.BuildConfig;import com.hirain.aiagent.rag.document.SourceCitationRenderer;import com.hirain.aiagent.rag.model.VehicleKnowledgeEvidence;import java.util.*;import java.util.regex.*;
/** 只接受当前 Request Evidence Map 中的显式 [E数字]；模型自行编造的页码或来源文字不构成引用。 */
public final class CitationGuard {private static final Pattern MARKER=Pattern.compile("\\[E(\\d+)\\]");private final SourceCitationRenderer renderer=new SourceCitationRenderer();public CitationValidationResult validate(String answer,Map<String,?> currentEvidence,boolean required){if(answer==null||answer.isBlank()){debug("empty-answer",Set.of(),currentEvidence);return CitationValidationResult.fail("KNOWLEDGE_CITATION_INVALID");}LinkedHashSet<String> ids=new LinkedHashSet<>();Matcher matcher=MARKER.matcher(answer);while(matcher.find())ids.add("E"+matcher.group(1));String output=answer;if(required&&ids.isEmpty()){if(currentEvidence==null||currentEvidence.isEmpty()){debug("missing-marker-without-evidence",ids,currentEvidence);return CitationValidationResult.fail("KNOWLEDGE_CITATION_INVALID");}ids.addAll(currentEvidence.keySet().stream().sorted(Comparator.comparingInt(CitationGuard::ordinal)).toList());output=answer+"\n\n依据："+ids.stream().map(id -> "["+id+"]").collect(java.util.stream.Collectors.joining(" "));debug("missing-marker-repaired",ids,currentEvidence);}for(String id:ids)if(currentEvidence==null||!currentEvidence.containsKey(id)){debug("unknown-marker",ids,currentEvidence);return CitationValidationResult.fail("KNOWLEDGE_CITATION_INVALID");}List<String> sources=new ArrayList<>();for(String id:ids){Object value=currentEvidence.get(id);if(value instanceof VehicleKnowledgeEvidence evidence)sources.add(renderer.render(id,evidence.documentTitle(),evidence.sourceLocator()));}if(!sources.isEmpty())output=output+"\n\n"+String.join("\n",sources);return new CitationValidationResult(true,output,"OK",List.copyOf(ids));}private static int ordinal(String id){try{return Integer.parseInt(id.substring(1));}catch(RuntimeException ignored){return Integer.MAX_VALUE;}}private static void debug(String reason,Set<String> ids,Map<String,?> currentEvidence){if(!BuildConfig.DEBUG)return;try{android.util.Log.d("RAG","citation reason="+reason+" extracted="+ids+" available="+(currentEvidence==null?Set.of():currentEvidence.keySet()));}catch(RuntimeException ignored){}}}
